using System.Collections.Generic;

namespace TAOM.Features.TroopProgression;

// Volunteer recruitment pool for South Rhovanion, the Northman horse-lords of the plains south of Mirkwood (troops generated by
// tools/generate_southrhovanion_troops.py). The data half of VolunteerRecruitmentService, registered by
// the static ctor in the core file. Lookup priority: conditional > settlement > clan > culture
// (troops.md).
public partial class VolunteerRecruitmentService
{
    private static void InitializeSouthRhovanionCulture()
    {
        // Two roots reach the whole tree: the Levy heads the spear and bow lines, and the Northman Youth heads the riders, the horse-archers and the Horse-lord. Levy-heavy, as Cardolan's.
        CultureMap["southrhovanion"] = new List<VolunteerChance>
        {
            new VolunteerChance("southrhovanion_levy", 6),
            new VolunteerChance("southrhovanion_northman_youth", 2)
        };
    }
}
